(() => {
  const canvas = document.querySelector('#world'), ctx = canvas.getContext('2d');
  const mini = document.querySelector('#minimap'), mx = mini.getContext('2d');
  const W = 2200, H = 1600, TAU = Math.PI * 2;
  const player = {x: 1080, y: 920, vx: 0, vy: 0, angle: -Math.PI/2, hp: 100, qi: 60, attack: 0, dash: 0, invuln: 0, skillCd: 0};
  let started = false, time = 0, kills = 0, questDone = false, defeated = 0, interacting = false, toastTimer = 0, music = false;
  const keys = new Set(), trees = [], rocks = [], grass = [], particles = [];
  const npcs = [{x:1085,y:1090,name:'Guru Shen',role:'Biarawan pengembara',color:'#b8b198',talked:false}];
  const enemies = [
    {x:560,y:620,hp:3,max:3,name:'Bandit',state:'idle',seed:1}, {x:755,y:520,hp:3,max:3,name:'Bandit',state:'idle',seed:2}, {x:1570,y:650,hp:3,max:3,name:'Bandit',state:'idle',seed:3},
    {x:1720,y:750,hp:5,max:5,name:'Pemimpin bandit',state:'idle',seed:4,boss:true}
  ];
  const path = [{x:1100,y:1480},{x:1050,y:1270},{x:1090,y:1080},{x:1110,y:900},{x:1080,y:700},{x:1120,y:510},{x:1330,y:390},{x:1580,y:470},{x:1780,y:650}];
  let seed = 19377; const rand=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
  for(let i=0;i<500;i++){let x=rand()*W,y=rand()*H;let nearPath=path.some((p,j)=>j<path.length-1&&distSeg(x,y,p,path[j+1])<65);let nearVillage=x>900&&x<1320&&y>1110&&y<1500;if(!nearPath&&!nearVillage)trees.push({x,y,r:15+rand()*22,type:rand(),shade:rand()});}
  for(let i=0;i<170;i++){let x=rand()*W,y=rand()*H;if(path.every((p,j)=>j===path.length-1||distSeg(x,y,p,path[j+1])>48))rocks.push({x,y,r:7+rand()*15});}
  for(let i=0;i<900;i++)grass.push({x:rand()*W,y:rand()*H,a:rand()*6.28,h:3+rand()*7});
  function distSeg(px,py,a,b){let dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((px-a.x)*dx+(py-a.y)*dy)/(dx*dx+dy*dy)));return Math.hypot(px-a.x-t*dx,py-a.y-t*dy)}
  let cw=0,ch=0,dpr=1,camera={x:0,y:0};
  function resize(){dpr=Math.min(devicePixelRatio||1,2);cw=innerWidth;ch=innerHeight;canvas.width=cw*dpr;canvas.height=ch*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)} addEventListener('resize',resize);resize();
  const $=s=>document.querySelector(s);
  function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');toastTimer=2.1}
  function addParticle(x,y,color,n=8){for(let i=0;i<n;i++){let a=rand()*TAU,s=35+rand()*150;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.45+rand()*.45,color,r:2+rand()*3})}}
  function attack(skill=false){if(!started)return;if(skill){if(player.skillCd>0)return;if(player.qi<18){toast('Qi belum cukup. Istirahat sejenak.');return}player.qi-=18;player.skillCd=4.5;player.attack=.42;addParticle(player.x+Math.cos(player.angle)*42,player.y+Math.sin(player.angle)*42,'#c7dfbb',24)}else player.attack=.27;
    const range=skill?145:90,arc=skill?2.2:1.55;let hit=false;
    for(const e of enemies){if(e.hp<=0)continue;let dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),ang=Math.atan2(dy,dx);if(d<range+18&&Math.abs(angleDiff(ang,player.angle))<arc){e.hp-=skill?2:1;e.state='aggro';e.stun=.35;addParticle(e.x,e.y,e.boss?'#e79b75':'#d8be82',11);hit=true;if(e.hp<=0){defeated++;player.qi=Math.min(60,player.qi+5);toast(e.boss?'Pemimpin bandit dikalahkan! +5 Qi':'Bandit dikalahkan · +5 Qi');if(defeated>=3&&!questDone){questDone=true;$('#questCheck').classList.add('done');$('#questProgress').textContent='3 / 3';$('#questObjective').textContent='Kembali kepada Guru Shen';}}} }
    if(!hit&&!skill){addParticle(player.x+Math.cos(player.angle)*39,player.y+Math.sin(player.angle)*39,'#d7c68c',4)}
  }
  function angleDiff(a,b){return Math.atan2(Math.sin(a-b),Math.cos(a-b))}
  function interact(){if(!started)return;let npc=npcs[0];if(Math.hypot(player.x-npc.x,player.y-npc.y)<100){if(!npc.talked){npc.talked=true;toast('Guru Shen: “Kabut menyembunyikan banyak hal, pengembara. Waspadalah di jalur utara.”');}else if(questDone){toast('Guru Shen: “Keberanian tanpa kebijaksanaan hanya badai. Terimalah ini.”');player.qi=60;$('#questObjective').textContent='Misi selesai · jelajahi Qinghe';$('#questProgress').textContent='SELESAI';$('#questCheck').classList.add('done');questDone='claimed';}else toast('Guru Shen: “Tiga bandit mengganggu jalur utara. Bantu para pelintas.”');return}toast('Tidak ada yang bisa diajak bicara di dekatmu.')}
  function showModal(title,content){$('#modalTitle').textContent=title;$('#modalContent').innerHTML=content;$('#modalBackdrop').classList.add('open')}
  function closeModal(){$('#modalBackdrop').classList.remove('open')}
  function mapModal(){showModal('Peta Provinsi Qinghe','<p>Jalur Cemara adalah persimpangan dagang di kaki Pegunungan Giok. Jalur utara menuju Hutan Seribu Pinus, sementara selatan turun ke dusun dan dermaga sungai.</p><div class="modal-grid"><div class="modal-tile"><b>Jalur Cemara</b><span>Area aman · Pengembara & pedagang</span></div><div class="modal-tile"><b>Hutan Pinus</b><span>Ancaman bandit · Level rekomendasi: bebas</span></div><div class="modal-tile"><b>Dusun Qinghe</b><span>Tempat beristirahat dan berdagang</span></div><div class="modal-tile"><b>Biara Awan Hening</b><span>Lokasi perguruan · terkunci untuk bab berikutnya</span></div></div>')}
  function journal(){showModal('Jurnal Perjalanan','<p><b>Jejak di Kabut</b><br>Gangguan bandit mengancam para pelintas di jalur gunung. Guru Shen meminta bantuanmu.</p><div class="modal-tile"><b>Tujuan</b><span>'+ (questDone==='claimed'?'Misi selesai. Qinghe kembali aman.':questDone?'Kembali kepada Guru Shen untuk menerima hadiah.':'Kalahkan bandit di jalur hutan ('+defeated+'/3).')+'</span></div><p style="margin-bottom:0">Setiap perguruan memiliki pandangan berbeda. Pilihanmu akan menentukan reputasi dan jalan yang terbuka.</p>')}
  function sect(){showModal('Perguruan Persilatan','<p>Di tanah Qinghe, ilmu diwariskan melalui laku, bukan sekadar tingkatan. Temukan guru yang sejalan dengan jalanmu.</p><div class="modal-grid"><div class="modal-tile"><b>Biara Awan Hening</b><span>Disiplin, pertahanan, dan telapak tangan.</span></div><div class="modal-tile"><b>Paviliun Pedang Wudang</b><span>Gerak melingkar, pedang, dan keseimbangan.</span></div><div class="modal-tile"><b>Aula Emei</b><span>Kecepatan, jarum tersembunyi, dan pemulihan.</span></div><div class="modal-tile"><b>Pengembara Sungai</b><span>Bebas perguruan. Selalu ada jalan lain.</span></div></div>')}
  function down(e){keys.add(e.key.toLowerCase());if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.repeat)return;let k=e.key.toLowerCase();if(k==='j')attack();if(k==='f')attack(true);if(k===' ')dash();if(k==='e')interact();if(k==='m')mapModal();if(k==='escape')closeModal();if(k==='u')sect();if(k==='l')journal()}
  function up(e){keys.delete(e.key.toLowerCase())}addEventListener('keydown',down);addEventListener('keyup',up);
  function dash(){if(!started||player.dash>0)return;let x=(keys.has('d')?1:0)-(keys.has('a')?1:0),y=(keys.has('s')?1:0)-(keys.has('w')?1:0);if(!x&&!y){x=Math.cos(player.angle);y=Math.sin(player.angle)}let l=Math.hypot(x,y)||1;player.vx=x/l*500;player.vy=y/l*500;player.dash=.22;player.invuln=.38;addParticle(player.x,player.y,'#c6d6bf',7)}
  $('#startBtn').onclick=()=>{started=true;$('#startOverlay').classList.add('hidden');toast('Perjalanan dimulai. Temui Guru Shen di dekat dusun.')};$('#attackBtn').onclick=()=>attack();$('#skillBtn').onclick=()=>attack(true);$('#dodgeBtn').onclick=dash;$('#mAttack').onclick=()=>attack();$('#mSkill').onclick=()=>attack(true);$('#mDodge').onclick=dash;$('#modalClose').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};$('#mapBtn').onclick=mapModal;$('#mapMenuBtn').onclick=mapModal;$('#journalBtn').onclick=journal;$('#sectBtn').onclick=sect;$('#soundBtn').onclick=e=>{music=!music;e.currentTarget.textContent=music?'♪':'♫';toast(music?'Suara ambience aktif':'Suara ambience nonaktif')};
  let joy=null;const stick=$('#joystick');stick.addEventListener('pointerdown',e=>{joy=e;stick.setPointerCapture(e.pointerId);joyMove(e)});stick.addEventListener('pointermove',e=>{if(joy)joyMove(e)});stick.addEventListener('pointerup',()=>joy=null);stick.addEventListener('pointercancel',()=>joy=null);function joyMove(e){let r=stick.getBoundingClientRect();let dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2);let l=Math.hypot(dx,dy),m=32;if(l>m){dx=dx/l*m;dy=dy/l*m}stick.firstElementChild.style.transform=`translate(${dx}px,${dy}px)`;joy={x:dx/m,y:dy/m}}
  function update(dt){time+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show')}player.attack=Math.max(0,player.attack-dt);player.dash=Math.max(0,player.dash-dt);player.invuln=Math.max(0,player.invuln-dt);player.skillCd=Math.max(0,player.skillCd-dt);player.qi=Math.min(60,player.qi+dt*.65);
    let x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),y=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(joy){x=joy.x;y=joy.y}if(!player.dash){let l=Math.hypot(x,y);if(l){x/=l;y/=l;player.angle=Math.atan2(y,x);player.vx+=(x*190-player.vx)*Math.min(1,dt*12);player.vy+=(y*190-player.vy)*Math.min(1,dt*12)}else{player.vx*=Math.max(0,1-dt*9);player.vy*=Math.max(0,1-dt*9)}}player.x=Math.max(55,Math.min(W-55,player.x+player.vx*dt));player.y=Math.max(55,Math.min(H-55,player.y+player.vy*dt));
    for(const e of enemies){if(e.hp<=0)continue;e.stun=Math.max(0,(e.stun||0)-dt);let d=Math.hypot(player.x-e.x,player.y-e.y);if(d<270)e.state='aggro';if(e.state==='aggro'&&e.stun<=0){if(d>43){e.x+=(player.x-e.x)/d*(e.boss?47:38)*dt;e.y+=(player.y-e.y)/d*(e.boss?47:38)*dt}else{e.hit=(e.hit||0)-dt;if(e.hit<=0&&player.invuln<=0){player.hp-=e.boss?11:7;e.hit=1.15;addParticle(player.x,player.y,'#dc8068',8);if(player.hp<=0){player.hp=100;player.x=1080;player.y=920;toast('Kamu tumbang, lalu tersadar kembali di jalur.')}}}}}
    for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.93;p.vy*=.93;if(p.life<=0)particles.splice(i,1)}camera.x=Math.max(0,Math.min(W-cw,player.x-cw/2));camera.y=Math.max(0,Math.min(H-ch,player.y-ch/2));updateHud();}
  function updateHud(){$('#hpBar').style.width=player.hp+'%';$('#qiBar').style.width=(player.qi/60*100)+'%';$('#hpText').textContent=Math.ceil(player.hp)+' / 100';$('#qiText').textContent=Math.floor(player.qi)+' / 60';$('#skillCooldown').style.transform=`scaleY(${Math.min(1,player.skillCd/4.5)})`;$('#questProgress').textContent=questDone?'3 / 3':`${defeated} / 3`;$('#timeLabel').textContent=((6+Math.floor(time/45))%24).toString().padStart(2,'0')+':'+(Math.floor((time%45)/.75)).toString().padStart(2,'0');let near=npcs.some(n=>Math.hypot(player.x-n.x,player.y-n.y)<100);$('#interactionHint').classList.toggle('visible',near);let fighting=enemies.some(e=>e.hp>0&&Math.hypot(player.x-e.x,player.y-e.y)<260);$('#combatBanner').classList.toggle('show',fighting);$('#locationName').textContent=player.y>1100?'Dusun Qinghe':player.x>1450?'Jalur Tebing':player.y<560?'Hutan Pinus':'Jalur Cemara'}
  function draw(){ctx.clearRect(0,0,cw,ch);ctx.save();ctx.translate(-camera.x,-camera.y);drawGround();drawPath();drawVillage();drawRuins();for(const r of rocks)drawRock(r);for(const t of trees)drawTree(t);for(const n of npcs)drawPerson(n.x,n.y,'#d3cba9',false,n.name);for(const e of enemies)if(e.hp>0)drawEnemy(e);drawPerson(player.x,player.y,'#b8c5a5',true,'Lin Yue');for(const p of particles){ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,TAU);ctx.fill()}ctx.globalAlpha=1;ctx.restore();drawAtmosphere();drawMini();}
  function drawGround(){let g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,'#53654e');g.addColorStop(.52,'#687050');g.addColorStop(1,'#405648');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.fillStyle='rgba(198,180,120,.08)';for(let i=0;i<grass.length;i++){let p=grass[i];ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.a);ctx.strokeStyle=i%3?'#aab47a33':'#d4c38b26';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,-p.h);ctx.stroke();ctx.restore()}for(let i=0;i<6;i++){ctx.fillStyle=`rgba(23,39,34,${.06+i*.009})`;ctx.beginPath();ctx.ellipse(450+i*355,190+i%2*180,290,95,-.2,0,TAU);ctx.fill()}}
  function drawPath(){ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();path.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle='#263a33';ctx.lineWidth=113;ctx.stroke();ctx.strokeStyle='#a2936c';ctx.lineWidth=93;ctx.stroke();ctx.strokeStyle='#b8aa7c';ctx.lineWidth=80;ctx.stroke();ctx.strokeStyle='#c2b58a';ctx.globalAlpha=.38;ctx.lineWidth=1;for(let i=0;i<230;i++){let p=path[Math.floor(rand()*path.length)];ctx.beginPath();ctx.arc(p.x+(rand()-.5)*100,p.y+(rand()-.5)*120,rand()*2,0,TAU);ctx.stroke()}ctx.globalAlpha=1}
  function drawTree(t){let x=t.x,y=t.y;ctx.fillStyle='#192d26';ctx.beginPath();ctx.ellipse(x+5,y+13,t.r*1.05,t.r*.55,0,0,TAU);ctx.fill();ctx.fillStyle='#493e2b';ctx.fillRect(x-3,y-t.r*.2,6,t.r*.85);let c=t.type>.66?'#344d3a':t.type>.33?'#40583d':'#4b6242';ctx.fillStyle=c;for(let j=0;j<3;j++){ctx.beginPath();ctx.moveTo(x,y-t.r*2.15+j*11);ctx.lineTo(x-t.r*(1-j*.16),y+t.r*.48-j*2);ctx.lineTo(x+t.r*(1-j*.16),y+t.r*.48-j*2);ctx.closePath();ctx.fill()}ctx.fillStyle='#a1a66d21';ctx.beginPath();ctx.ellipse(x-t.r*.26,y-t.r*.9,t.r*.29,t.r*.48,-.4,0,TAU);ctx.fill()}
  function drawRock(r){ctx.fillStyle='#273b34';ctx.beginPath();ctx.ellipse(r.x+3,r.y+4,r.r*1.2,r.r*.7,0,0,TAU);ctx.fill();ctx.fillStyle='#727766';ctx.beginPath();ctx.moveTo(r.x-r.r,r.y+r.r*.3);ctx.lineTo(r.x-r.r*.65,r.y-r.r*.6);ctx.lineTo(r.x+r.r*.25,r.y-r.r);ctx.lineTo(r.x+r.r,r.y-r.r*.15);ctx.lineTo(r.x+r.r*.55,r.y+r.r*.56);ctx.closePath();ctx.fill();ctx.fillStyle='#a7a58a55';ctx.beginPath();ctx.moveTo(r.x-r.r*.5,r.y-r.r*.45);ctx.lineTo(r.x+r.r*.25,r.y-r.r);ctx.lineTo(r.x+r.r*.1,r.y);ctx.closePath();ctx.fill()}
  function drawVillage(){// small roadside tea house and clustered homes
    [[1030,1330,1],[1175,1395,.82],[970,1465,.7]].forEach(([x,y,s],i)=>{ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#26382e';ctx.fillRect(-47,-16,94,58);ctx.fillStyle='#c6b58c';ctx.fillRect(-42,-12,84,48);ctx.fillStyle='#544335';ctx.fillRect(-7,13,16,23);ctx.fillStyle='#374337';ctx.beginPath();ctx.moveTo(-62,-14);ctx.lineTo(0,-53);ctx.lineTo(61,-14);ctx.lineTo(47,-10);ctx.lineTo(0,-40);ctx.lineTo(-48,-8);ctx.closePath();ctx.fill();ctx.fillStyle='#76664b';ctx.fillRect(-54,-16,108,5);if(i===0){ctx.fillStyle='#dfb56c';ctx.fillRect(25,2,7,10);ctx.fillStyle='#e3ba7166';ctx.beginPath();ctx.arc(28,7,17,0,TAU);ctx.fill()}ctx.restore()});
    // bridge over stream
    ctx.fillStyle='#506d6b';ctx.beginPath();ctx.moveTo(750,1450);ctx.quadraticCurveTo(840,1418,925,1452);ctx.lineTo(925,1488);ctx.quadraticCurveTo(840,1456,750,1490);ctx.closePath();ctx.fill();ctx.fillStyle='#8c7953';ctx.fillRect(758,1449,165,14);for(let i=0;i<7;i++){ctx.fillStyle='#574b37';ctx.fillRect(766+i*22,1447,3,17)}
  }
  function drawRuins(){// distant gate and mountain layers
    ctx.fillStyle='#2d4038';ctx.beginPath();ctx.moveTo(0,250);ctx.lineTo(220,90);ctx.lineTo(360,255);ctx.lineTo(520,115);ctx.lineTo(720,300);ctx.lineTo(900,130);ctx.lineTo(1110,330);ctx.lineTo(1300,145);ctx.lineTo(1510,330);ctx.lineTo(1750,105);ctx.lineTo(1980,310);ctx.lineTo(2200,135);ctx.lineTo(2200,0);ctx.lineTo(0,0);ctx.closePath();ctx.fill();ctx.fillStyle='#83907820';for(let i=0;i<7;i++){ctx.beginPath();ctx.moveTo(i*390,200);ctx.lineTo(i*390+160,100);ctx.lineTo(i*390+290,222);ctx.fill()}// distant monastery gate
    ctx.fillStyle='#354237';ctx.fillRect(1040,375,17,115);ctx.fillRect(1160,375,17,115);ctx.fillRect(1028,360,160,17);ctx.fillStyle='#725c3e';ctx.fillRect(1075,398,68,92);ctx.fillStyle='#baab78';ctx.fillRect(1083,408,52,82);ctx.fillStyle='#344339';ctx.beginPath();ctx.moveTo(1018,365);ctx.lineTo(1100,324);ctx.lineTo(1198,365);ctx.lineTo(1178,372);ctx.lineTo(1100,341);ctx.lineTo(1036,372);ctx.fill();ctx.fillStyle='#cab783';ctx.font='12px serif';ctx.fillText('雲',1091,388)
  }
